const root = '/home/cassandra/tradecloseout';
const {createRequire} = require('node:module');
const {randomUUID,randomBytes,createHash} = require('node:crypto');
const fs = require('node:fs');
const req = createRequire(`${root}/apps/api/package.json`);
const {Test} = req('@nestjs/testing');
const {Pool} = req('pg');
const {ValidationPipe} = req('@nestjs/common');
const Redis = req('ioredis');
const pick = (m,k) => m[k] || m.default[k];
const compiled = `${root}/apps/api/dist/apps/api/src`;
const {AppModule} = require(`${compiled}/app.module.js`);
const {TenantDbService} = require(`${compiled}/database/tenant-db.service.js`);
const {ProblemJsonExceptionFilter} = require(`${compiled}/common/filters/problem-json.filter.js`);
const {VisibilityProjectionInterceptor} = require(`${compiled}/common/interceptors/visibility-projection.interceptor.js`);
const results=[];
(async()=>{
 process.env.NODE_ENV='test';
 process.env.REDIS_URL ||= 'redis://127.0.0.1:6379';
 const helper=await import(`${root}/packages/db/test/helpers/disposable-database.ts`);
 const fixtures=await import(`${root}/packages/db/test/helpers/fixtures.ts`);
 await pick(helper,'withDisposableDatabase')(async ({admin,app:pool})=>{
  const {userId,tenants:[a]}=await pick(fixtures,'seedTenants')(admin);
  await admin.query(`INSERT INTO memberships(id,org_id,user_id,role,status) VALUES($1,$2,$3,'R-OWNER','ACTIVE')`,[randomUUID(),a.orgId,userId]);
  const token=randomBytes(32).toString('hex'),csrf=randomBytes(24).toString('hex');
  const hash=x=>createHash('sha256').update(x).digest('hex');
  const session=randomUUID();
  await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,expires_at) VALUES($1,$2,$3,$4,$5,now()+interval '1 day')`,[session,userId,hash(token),hash(csrf),a.orgId]);
  const module=await Test.createTestingModule({imports:[AppModule]})
   .overrideProvider(Pool).useValue(pool)
   .overrideProvider(TenantDbService).useValue(new TenantDbService(pool)).compile();
  const app=module.createNestApplication({logger:false});
  app.use(req('cookie-parser')());
  app.useGlobalPipes(new ValidationPipe({whitelist:true,transform:true}));
  app.useGlobalFilters(new ProblemJsonExceptionFilter());
  app.useGlobalInterceptors(new VisibilityProjectionInterceptor());
  try {
   await app.listen(0,'127.0.0.1');
   const base=await app.getUrl();
   async function get(label,path,cookie=token){
    const response=await fetch(base+path,{headers:{Cookie:`tc_session=${cookie}`}});
    const body=await response.json().catch(()=>null);
    if(label==='consultant_projection')results.push({label,status:response.status,internalSettingsVisible:body?.settings_json?.internal_note==='synthetic confidential note'});
    else results.push({label,status:response.status,body:Array.isArray(body)?{count:body.length,projectIds:body.map(x=>x.id)}:body});
   }
   await get('owner_auth_me','/api/v1/auth/me');
   await get('owner_auth_orgs','/api/v1/auth/orgs');
   await get('versioned_work_items','/api/v1/work-items');
   await get('unversioned_work_items','/work-items');
   await get('versioned_commissioning',`/api/v1/projects/${a.projectIds[0]}/commissioning/tab-worksheets`);
   await get('unversioned_commissioning',`/projects/${a.projectIds[0]}/commissioning/tab-worksheets`);
   const party=randomUUID(),grant=randomUUID(),guestToken=randomBytes(32).toString('hex');
   await admin.query(`INSERT INTO parties(id,org_id,name,types,status) VALUES($1,$2,'Scoped external client',ARRAY['CLIENT'],'ACTIVE')`,[party,a.orgId]);
   await admin.query(`INSERT INTO guest_grants(id,org_id,project_id,party_id,target_email,grant_type,role,capabilities,scope_json,token_hash,expires_at,created_by) VALUES($1,$2,$3,$4,'probe@example.invalid','CLIENT_VIEW','R-CLIENT',ARRAY['project.read','asset.read'],'{}',$5,now()+interval '1 day',$6)`,[grant,a.orgId,a.projectIds[0],party,hash(randomUUID()),userId]);
   await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,guest_grant_id,expires_at) VALUES($1,$2,$3,$4,$5,$6,now()+interval '1 day')`,[randomUUID(),userId,hash(guestToken),hash(csrf),a.orgId,grant]);
   await get('guest_project_list_scoped_to_project_0','/api/v1/projects',guestToken);
   await get('guest_reads_other_project',`/api/v1/projects/${a.projectIds[1]}`,guestToken);
   await admin.query(`UPDATE projects SET settings_json=$1 WHERE id=$2`,[JSON.stringify({internal_note:'synthetic confidential note',supplier_price:123}),a.projectIds[0]]);
   await admin.query(`UPDATE guest_grants SET role='R-CONSULT' WHERE id=$1`,[grant]);
   await get('consultant_projection',`/api/v1/projects/${a.projectIds[0]}`,guestToken);
   const portalResponse=await fetch(base+`/api/v1/submissions/${randomUUID()}/recipients/${randomUUID()}/decision`,{method:'POST',headers:{Cookie:`tc_session=${token}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:JSON.stringify({decision:'ACCEPTED',remarks:'Payload emitted by current guest page'})});
   results.push({label:'current_guest_page_decision_payload',status:portalResponse.status,body:await portalResponse.json()});
   const response=await fetch(base+'/api/v1/auth/logout',{method:'POST',headers:{Cookie:`tc_session=${token}`,'X-CSRF-Token':csrf}});
   results.push({label:'owner_logout',status:response.status});
   const row=await admin.query(`SELECT revoked_at FROM sessions WHERE id=$1`,[session]);
   results.push({label:'logout_persisted_revocation',revoked:row.rows[0]?.revoked_at!=null});
  }finally{
   app.get(Redis).disconnect();
   await app.close();
  }
 });
 fs.writeFileSync('/tmp/tradecloseout-production-http-results.json',JSON.stringify(results,null,2)+'\n');
 for(const result of results)console.log(JSON.stringify(result));
})().catch(e=>{console.error('PROBE_FAILED',e.message);process.exitCode=1});

